<script type="text/javascript">
			
               function drawCanvas() {
				var b = document.body.clientWidth,
				d = 160,
				c = document.getElementById("headerWhiteBg");
				c.style.width = b + "px";
				c.style.height = d + "px";
				c.width = b;
				c.height = d;
				var a = c.getContext("2d");
				a.moveTo(0, 41);
				a.lineTo(parseInt(b / 2), 0);
				a.lineTo(b, 41);
				a.closePath();
				a.fillStyle = "#ffffff";
				a.fill();
				a.lineWidth = 1;
				a.strokeStyle = "#ffffff";
				a.stroke();
				a.beginPath();
				a.moveTo(0, 41);
				a.lineTo(b, 41);
				a.lineTo(b, d);
				a.lineTo(0, d);
				a.closePath();
				a.fillStyle = "#ffffff";
				a.fill();
				a.lineWidth = 1;
				a.strokeStyle = "#ffffff";
				a.stroke()
			}
			document.addEventListener("DOMContentLoaded", drawCanvas, false);

            </script>

			
  <script type="text/javascript">

  var u = navigator.userAgent;

  var isAndroid = u.indexOf('Android') > -1 || u.indexOf('Adr') > -1; //android终端

  var isiOS = !!u.match(/\(i[^;]+;( U;)? CPU.+Mac OS X/); //ios终端

 
  if(isAndroid==true && isiOS==false){
	  target=document.getElementById('android-app');  
	  target.style.display="none";  
  }else if(isAndroid==false && isiOS==true){
	  target=document.getElementById('ios-app');  
	  target.style.display="none";  
  }
 
 
 
 

 </script>
 
 
