<script>
    var ua = navigator.userAgent.toLowerCase(),
        tip = $(".weixin-tip"),
        tipImg = $(".J-weixin-tip-img"),
        iosApp = $(".ios-app"),
        androidApp = $(".android-app"),
        wrapper = $(".wrapper"),
        iosAppLink = "",
        iosValidateLink = "",
        androidAppLink = "";


    if (ua.indexOf('micromessenger') != -1) {
        tip.show();
        tipImg.show();
        if (ua.indexOf('iphone') != -1 || ua.indexOf('ipad') != -1 || ua.indexOf('ipod') != -1) {
            tipImg.attr('class', 'J-weixin-tip-img weixin-tip-img iphone');
        } else {
            tipImg.attr('class', 'J-weixin-tip-img weixin-tip-img android');
        }
    } else {
        wrapper.show();
        if (ua.indexOf('iphone') != -1 || ua.indexOf('ipad') != -1 || ua.indexOf('ipod') != -1) {
            androidApp.hide();
        } else {
            iosApp.hide();
        }
    }

    iosApp.click(function () {
        layer.load();
        location.href = iosAppLink;

        setTimeout(function () {
            layer.open(
                {
                    content: '安装完成，信任描述文件以打开APP？',
                    skin: 'layer-ui-top',
                    btn: '好的',
                    yes: function () {
                        location.href = iosValidateLink;
                        layer.closeAll();
                    }
                }
            )
        }, 3000);
    });

    androidApp.click(function () {
        location.href = androidAppLink;

        layer.open(
            {
                content: '正在下载APP，请在下载完成后打开',
                skin: 'layer-ui-top',
                btn: '好的'
            }
        );
    });

</script>

